-- The Evergreen arrow when the guide module is on, else the game's own map pin (+ TomTom).
function P.Waypoint(map, x, y, title)
  if not map or not x or not y then say("no map position for " .. (title or "that") .. "."); return false end
  if ns.SetExternalTarget and ns.ModuleEnabled and ns.ModuleEnabled("guide") and EvergreenCharDB then
    ns.SetExternalTarget(map, x, y, title)
  else
    if C_Map and C_Map.SetUserWaypoint and UiMapPoint and UiMapPoint.CreateFromCoordinates then
      pcall(function()
        C_Map.SetUserWaypoint(UiMapPoint.CreateFromCoordinates(map, x / 100, y / 100))
        if C_SuperTrack and C_SuperTrack.SetSuperTrackedUserWaypoint then C_SuperTrack.SetSuperTrackedUserWaypoint(true) end
      end)
    end
    if TomTom and TomTom.AddWaypoint then pcall(TomTom.AddWaypoint, TomTom, map, x / 100, y / 100, { title = title }) end
  end
  say("waypoint: " .. HEX.body .. (title or "") .. "|r, " .. (P.ZONES[map] or ("map " .. map)) .. string.format(" %.1f, %.1f", x, y))
  return true
end

function P.WaypointNPC(slug)
  local n = P.NPC(slug)
  if not n then say("no position for that NPC."); return false end
  return P.Waypoint(n.m, n.x, n.y, n.n)
end

function P.NPCLabel(slug)
  local n = P.NPC(slug)
  if not n then return slug end
  local where = n.sub and n.z and n.sub ~= n.z and (n.sub .. ", " .. n.z) or n.z or (n.m and P.ZONES[n.m]) or ""
  return n.n .. (where ~= "" and (HEX.muted .. "  " .. where .. "|r") or "")
end

-- ------------------------------------------------------------------ shopping list ticks (per character)
local function shopKey(g, li, ri) return g.key .. ":" .. li .. ":" .. ri end
function P.ShopChecked(g, li, ri) return CDB and CDB.shop[shopKey(g, li, ri)] or false end
function P.SetShopChecked(g, li, ri, on) if CDB then CDB.shop[shopKey(g, li, ri)] = on and true or nil end end

-- ------------------------------------------------------------------ boot, events, slash
function P.DefaultGuide()
  if DB and DB.prof and P.Guide(DB.prof) then return P.Guide(DB.prof) end
  local learned = P.Learned()
  local secondary = { ["first-aid"] = true, cooking = true, fishing = true, ["fishing-and-cooking"] = true }
  for _, g in ipairs(learned) do if not secondary[g.key] then return g end end
  return learned[1] or P.Guides()[1]
end

function P.Select(key)
  local g = P.Guide(key)
  if not g then return nil end
  P.current = g
  if DB then DB.prof = key end
  if P.ui.Refresh then P.ui.Refresh() end
  return g
end

local pending
function P.Changed()
  if pending then return end
  pending = true
  local function run()
    pending = false
    P.ScanSkills()
    if P.ui.Refresh and P.ui.frame and P.ui.frame:IsShown() then P.ui.Refresh() end
  end
  if C_Timer and C_Timer.After then C_Timer.After(0.2, run) else run() end
end

local ev = CreateFrame("Frame")
ev:RegisterEvent("ADDON_LOADED")
ev:SetScript("OnEvent", function(self, event, name)
  if event == "ADDON_LOADED" then
    if name ~= ADDON then return end
    if not ns.ModuleEnabled("professions") then ns.Professions = nil; self:UnregisterAllEvents(); return end
    EvergreenDB = EvergreenDB or {}
    EvergreenDB.professions = EvergreenDB.professions or {}
    DB = EvergreenDB.professions
    DB.variants = DB.variants or {}
    EvergreenCharDB = EvergreenCharDB or {}
    EvergreenCharDB.professions = EvergreenCharDB.professions or {}
    CDB = EvergreenCharDB.professions
    CDB.shop = CDB.shop or {}
    P.db, P.cdb = DB, CDB
    for _, e in ipairs({ "PLAYER_LOGIN", "SKILL_LINES_CHANGED", "TRADE_SKILL_SHOW", "TRADE_SKILL_LIST_UPDATE",
                         "TRADE_SKILL_UPDATE", "CHAT_MSG_SKILL", "LEARNED_SPELL_IN_TAB", "BAG_UPDATE_DELAYED",
                         "BANKFRAME_OPENED", "PLAYERBANKSLOTS_CHANGED" }) do
      pcall(self.RegisterEvent, self, e)
    end
    P.ScanSkills()
    return
  end
  if event == "PLAYER_LOGIN" then
    P.ScanSkills()
    if ns.Skin.MinimapButton then
      ns.Skin.MinimapButton("professions", "Interface\\Icons\\Trade_BlackSmithing", 200,
        function() P.Slash("") end,
        function(tt)
          tt:AddLine("Evergreen: profession guides", 1, 0.82, 0)
          tt:AddLine("Click: open the guide for your professions", 0.9, 0.9, 0.9)
        end)
    end
    return
  end
  if event == "TRADE_SKILL_SHOW" or event == "TRADE_SKILL_LIST_UPDATE" or event == "TRADE_SKILL_UPDATE" then
    P.ReadTradeSkillWindow()
  end
  P.Changed()
end)

function P.Slash(rest)
  rest = (rest or ""):gsub("^%s+", ""):gsub("%s+$", "")
  local low = rest:lower()
  if low == "help" then
    say("/prof (toggle), /prof <profession> (open it), /prof clear (drop the waypoint), /prof skills (what the client reports)")
    return
  elseif low == "clear" then
    if ns.ClearExternalTarget then ns.ClearExternalTarget() end
    if C_Map and C_Map.ClearUserWaypoint then pcall(C_Map.ClearUserWaypoint) end
    say("waypoint cleared.")
    return
  elseif low == "skills" then
    P.ScanSkills()
    local t = {}
    for n, e in pairs(P.skills) do t[#t + 1] = n .. " " .. e.rank .. (e.max and ("/" .. e.max) or "") end
    table.sort(t)
    say(#t > 0 and table.concat(t, ", ") or "the client reported no skills.")
    return
  end
  if not P.ui.Build then return end
  P.ScanSkills()
  if low ~= "" then
    for _, g in ipairs(P.Guides()) do
      if g.key == low or g.name:lower():find(low, 1, true) then
        P.ui.Open(g.key)
        return
      end
    end
    if P.Data() then say("no profession guide matches '" .. rest .. "'."); return end
  end
  P.ui.Toggle()
end

SLASH_EVERGREENPROF1 = "/prof"
SLASH_EVERGREENPROF2 = "/professions"
SlashCmdList["EVERGREENPROF"] = function(msg)
  if not ns.Professions then
    print(HEX.green .. "Evergreen:|r the Professions module is off. Turn on \"Evergreen - Professions\" in the AddOns list, then /reload.")
    return
  end
  P.Slash(msg)
end

-- /eg prof: the core's /eg handler knows only its own modules, so wrap it (the core loads first)
local egSlash = SlashCmdList["EVERGREEN"]
if egSlash then
  SlashCmdList["EVERGREEN"] = function(msg)
    local cmd, rest = (msg or ""):match("^%s*(%S+)%s*(.-)%s*$")
    cmd = cmd and cmd:lower()
    if cmd == "prof" or cmd == "profs" or cmd == "profession" or cmd == "professions" then
      return SlashCmdList.EVERGREENPROF(rest)
    end
    egSlash(msg)
    if cmd == "help" or cmd == "?" then print(HEX.green .. "Professions|r: /eg prof, /prof") end
  end
end

-- listed by /eg modules
if type(ns.MODULES) == "table" then
  local known = false
  for _, m in ipairs(ns.MODULES) do if m.id == "professions" then known = true end end
  if not known then
    table.insert(ns.MODULES, { id = "professions", addon = "Evergreen_Professions", name = "Professions", slash = "/prof",
      desc = "Profession leveling guides (WoW-Professions.com): steps, materials, trainers, shopping list" })
  end
end
